import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'
import { urls } from 'scenes/urls'

import { Breadcrumb } from '~/types'

import { canvasesList } from '../generated/api'
import type { CanvasApi, PaginatedCanvasListApi } from '../generated/api.schemas'
import { deleteCanvasWithUndo } from '../scene/deleteCanvasWithUndo'

export const CANVASES_PAGE_SIZE = 50

export type CanvasesOrdering = '-updated_at' | '-created_at'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasesListLogicValues {
    currentTeamId: number | null // teamLogic
    breadcrumbs: Breadcrumb[]
    canvases: CanvasApi[]
    canvasesResponse: PaginatedCanvasListApi | null
    canvasesResponseLoading: boolean
    hiddenIds: string[]
    ordering: CanvasesOrdering
    page: number
    search: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasesListLogicActions {
    deleteCanvas: (canvas: CanvasApi) => {
        canvas: CanvasApi
    }
    hideCanvas: (id: string) => {
        id: string
    }
    loadCanvases: (_: void) => void
    loadCanvasesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCanvasesSuccess: (
        canvasesResponse: PaginatedCanvasListApi | null,
        payload?: void
    ) => {
        canvasesResponse: PaginatedCanvasListApi | null
        payload?: void
    }
    restoreCanvas: (id: string) => {
        id: string
    }
    setOrdering: (ordering: CanvasesOrdering) => {
        ordering: CanvasesOrdering
    }
    setPage: (page: number) => {
        page: number
    }
    setSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasesListLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        canvases: (canvasesResponse: PaginatedCanvasListApi | null, hiddenIds: string[]) => CanvasApi[]
    }
}

export type canvasesListLogicType = MakeLogicType<
    canvasesListLogicValues,
    canvasesListLogicActions,
    Record<string, any>,
    canvasesListLogicMeta
>

export const canvasesListLogic = kea<canvasesListLogicType>([
    path(['products', 'canvas', 'frontend', 'list', 'canvasesListLogic']),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),
    actions({
        setSearch: (search: string) => ({ search }),
        setOrdering: (ordering: CanvasesOrdering) => ({ ordering }),
        setPage: (page: number) => ({ page }),
        deleteCanvas: (canvas: CanvasApi) => ({ canvas }),
        hideCanvas: (id: string) => ({ id }),
        restoreCanvas: (id: string) => ({ id }),
    }),
    reducers({
        search: ['', { setSearch: (_, { search }) => search }],
        ordering: ['-updated_at' as CanvasesOrdering, { setOrdering: (_, { ordering }) => ordering }],
        page: [
            1,
            {
                setPage: (_, { page }) => page,
                setSearch: () => 1,
                setOrdering: () => 1,
            },
        ],
        // Rows deleted in this session stay hidden through the undo window, before the server knows.
        hiddenIds: [
            [] as string[],
            {
                hideCanvas: (state, { id }) => [...state, id],
                restoreCanvas: (state, { id }) => state.filter((hiddenId) => hiddenId !== id),
            },
        ],
    }),
    loaders(({ values }) => ({
        canvasesResponse: [
            null as PaginatedCanvasListApi | null,
            {
                loadCanvases: async (_: void, breakpoint) => {
                    if (!values.currentTeamId) {
                        return null
                    }
                    const response = await canvasesList(String(values.currentTeamId), {
                        // Component canvases are widgets that grids place, not canvases a person opens.
                        kind: 'freeform',
                        search: values.search.trim() || undefined,
                        ordering: values.ordering,
                        limit: CANVASES_PAGE_SIZE,
                        offset: (values.page - 1) * CANVASES_PAGE_SIZE,
                    })
                    // A newer search, sort, or page supersedes this response.
                    breakpoint()
                    return response
                },
            },
        ],
    })),
    selectors({
        canvases: [
            (s) => [s.canvasesResponse, s.hiddenIds],
            (response: PaginatedCanvasListApi | null, hiddenIds: string[]): CanvasApi[] =>
                (response?.results ?? []).filter((canvas) => !hiddenIds.includes(canvas.id)),
        ],
        breadcrumbs: [() => [], (): Breadcrumb[] => [{ key: 'Canvases', name: 'Canvases', path: urls.canvases() }]],
    }),
    listeners(({ actions, values }) => ({
        setSearch: async (_, breakpoint) => {
            await breakpoint(300)
            actions.loadCanvases()
        },
        setOrdering: () => actions.loadCanvases(),
        setPage: () => actions.loadCanvases(),
        deleteCanvas: ({ canvas }) => {
            if (!values.currentTeamId) {
                return
            }
            actions.hideCanvas(canvas.id)
            deleteCanvasWithUndo({
                projectId: String(values.currentTeamId),
                canvasId: canvas.id,
                spaceId: canvas.channel,
                name: canvas.name || 'Untitled canvas',
                surface: 'web_canvases_list',
                onRestore: () => actions.restoreCanvas(canvas.id),
            })
        },
    })),
])
